import ast, pathlib, sys

BUILTIN_GENERICS = {"list","dict","set","frozenset","tuple","type"}

class V(ast.NodeVisitor):
    def __init__(self, path):
        self.path = path
        self.ann_depth = 0
    # annotation contexts are lazy thanks to `from __future__ import annotations`
    def visit_AnnAssign(self, node):
        if node.value: self.visit(node.value)
        # skip node.annotation
    def visit_FunctionDef(self, node):
        self._func(node)
    def visit_AsyncFunctionDef(self, node):
        self._func(node)
    def _func(self, node):
        for d in node.decorator_list: self.visit(d)
        a = node.args
        for default in a.defaults + [d for d in a.kw_defaults if d]:
            self.visit(default)
        for st in node.body: self.visit(st)
    def visit_arg(self, node):
        pass
    def visit_Subscript(self, node):
        v = node.value
        if isinstance(v, ast.Name) and v.id in BUILTIN_GENERICS:
            print(f"{self.path}:{node.lineno}: RUNTIME builtin generic subscript: {ast.unparse(node)}")
        if isinstance(v, ast.Attribute):
            print(f"{self.path}:{node.lineno}: runtime attr subscript: {ast.unparse(node)}")
        self.generic_visit(node)
    def visit_BinOp(self, node):
        if isinstance(node.op, ast.BitOr):
            print(f"{self.path}:{node.lineno}: RUNTIME `|` BinOp: {ast.unparse(node)}")
        self.generic_visit(node)

for p in sorted(pathlib.Path('/workspace/src/stamina').rglob('*.py')):
    tree = ast.parse(p.read_text())
    V(str(p)).visit(tree)
print("scan done")
